#!/usr/bin/env bash
# ============================================================================
# VideoMind Redesign - Part 3: Video workspace polish
# ============================================================================
# Presentation only + two real back-link fixes. No logic touched.
#
#   Edits: frontend/src/app/video/[id]/page.tsx        (spacing, /library links)
#          frontend/src/components/video/InsightsPanel.tsx  (padding rhythm)
#          frontend/src/components/video/OnChainProof.tsx   (padding rhythm)
#
# Does NOT touch VideoPlayer, IntelligenceStrip, ChatPanel, useOnChainBlob,
# any lib/, or any seek/query/duration logic. Tab labels unchanged.
# Requires Part 1 + Part 2 applied first.
#
#   ./vm_part3_workspace.sh          apply
#   ./vm_part3_workspace.sh --revert restore all three from backups
# ============================================================================
set -euo pipefail

WS="frontend/src/app/video/[id]/page.tsx"
INS="frontend/src/components/video/InsightsPanel.tsx"
OCP="frontend/src/components/video/OnChainProof.tsx"
GLOBALS="frontend/src/app/globals.css"
NAV="frontend/src/components/layout/Navbar.tsx"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR="frontend/.vm_part3_backups"

say() { printf '  %s\n' "$1"; }
die() { printf 'ERROR: %s\n' "$1" >&2; exit 1; }

[ -f "$WS" ] || die "$WS not found. Run from the repo root (folder containing frontend/)."

# ---- revert -----------------------------------------------------------------
if [ "${1:-}" = "--revert" ]; then
  [ -d "$BAKDIR" ] || die "No backup dir ($BAKDIR). Nothing to revert."
  LATEST="$(ls -1d $BAKDIR/*/ 2>/dev/null | sort | tail -1)"
  [ -n "$LATEST" ] || die "No backups found."
  cp "$LATEST/page.tsx"          "$WS"
  cp "$LATEST/InsightsPanel.tsx" "$INS"
  cp "$LATEST/OnChainProof.tsx"  "$OCP"
  say "Reverted 3 files from $LATEST"
  exit 0
fi

# ---- guards -----------------------------------------------------------------
grep -q "VM_PART1_FOUNDATION" "$GLOBALS" 2>/dev/null || die "Part 1 not applied. Run ./vm_part1_foundation.sh first."
grep -q '"/library"' "$NAV" 2>/dev/null || die "Part 2 not applied. Run ./vm_part2_landing.sh first."

if grep -q 'href="/library"' "$WS" 2>/dev/null && grep -q 'className="section' "$WS" 2>/dev/null; then
  say "Part 3 already applied (workspace uses /library + section). Use --revert to undo."
  exit 0
fi

# ---- backup ----------------------------------------------------------------
mkdir -p "$BAKDIR/$STAMP"
cp "$WS"  "$BAKDIR/$STAMP/page.tsx"
cp "$INS" "$BAKDIR/$STAMP/InsightsPanel.tsx"
cp "$OCP" "$BAKDIR/$STAMP/OnChainProof.tsx"
say "Backups saved to $BAKDIR/$STAMP/"

# ---- decode + verify before writing ----------------------------------------
decode() {
  local tmp; tmp="$(mktemp)"
  printf '%s' "$1" | base64 -d > "$tmp" || die "$3: base64 decode failed."
  grep -q "$2" "$tmp" || die "$3: payload verify failed (missing '$2'). Nothing written."
  printf '%s' "$tmp"
}
T_WS="$(decode "" 'href="/library"' "workspace")"
T_INS="$(decode "" 'export function InsightsPanel' "InsightsPanel")"
T_OCP="$(decode "" 'export function OnChainProof' "OnChainProof")"

# extra safety: confirm logic markers survived in payloads
grep -q "useOnChainBlob" "$T_OCP" || die "OnChainProof payload missing data hook - aborting."
grep -q "IntelligenceStrip" "$T_WS" || die "workspace payload missing IntelligenceStrip - aborting."

cp "$T_WS" "$WS"; cp "$T_INS" "$INS"; cp "$T_OCP" "$OCP"
rm -f "$T_WS" "$T_INS" "$T_OCP"

# ---- post-write verify ------------------------------------------------------
grep -q 'href="/library"' "$WS" || die "workspace verify failed - restore from $BAKDIR/$STAMP"
grep -q "export function InsightsPanel" "$INS" || die "InsightsPanel verify failed."
grep -q "useOnChainBlob" "$OCP" || die "OnChainProof verify failed - data hook missing!"

say "Applied Part 3: workspace + InsightsPanel + OnChainProof polished."
say "  Back-links fixed to /library. All seek/chain logic untouched."
say "Next: cd frontend && npm run build   (verify locally before deploying)"
